```python
"""
Script para asignar el claim 'admin: true' a un usuario de Firebase Auth.

Uso:
    python set_admin_claim.py <email_del_admin>

Ejemplo:
    python set_admin_claim.py admin@lacatrina.com

Requisitos:
    - serviceAccountKey.json en la misma carpeta
    - firebase-admin instalado (pip install firebase-admin)
    - El usuario debe existir previamente en Firebase Auth
      (creado desde la consola de Firebase)
"""

import sys
import firebase_admin
from firebase_admin import credentials, auth

FIREBASE_CRED_PATH = "./serviceAccountKey.json"


def set_admin_claim(email):
    cred = credentials.Certificate(FIREBASE_CRED_PATH)
    if not firebase_admin._apps:
        firebase_admin.initialize_app(cred)

    try:
        user = auth.get_user_by_email(email)
        auth.set_custom_user_claims(user.uid, {'admin': True})
        print(f"✅ Claim 'admin: true' asignado a {email}")
        print(f"   UID: {user.uid}")
        print()
        print("NOTA: El cambio puede tardar hasta 1 hora en propagarse.")
        print("      Para que sea inmediato, cierra sesión y vuelve a entrar en el panel admin.")
    except firebase_admin.auth.UserNotFoundError:
        print(f"❌ No se encontró ningún usuario con el email: {email}")
        print("   Crea el usuario primero en Firebase Console > Authentication > Users.")
        sys.exit(1)
    except Exception as e:
        print(f"❌ Error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Uso: python set_admin_claim.py <email_del_admin>")
        print("Ejemplo: python set_admin_claim.py admin@lacatrina.com")
        sys.exit(1)
    set_admin_claim(sys.argv[1])
```

