const [email, setEmail] = useState('');
const [password, setPassword] = useState('');
const [user, setUser] = useState(null);
const [isAdmin, setIsAdmin] = useState(false);
const [authLoading, setAuthLoading] = useState(true);
const [loginError, setLoginError] = useState('');
const [songs, setSongs] = useState([]);
const [nowPlaying, setNowPlaying] = useState(null);

// Auth state listener — verifica autenticación y claim de admin
useEffect(() => {
  const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
    if (firebaseUser) {
      setUser(firebaseUser);
      try {
        const tokenResult = await firebaseUser.getIdTokenResult();
        setIsAdmin(tokenResult.claims.admin === true);
      } catch (e) {
        console.error('Error verificando claim de admin:', e);
        setIsAdmin(false);
      }
    } else {
      setUser(null);
      setIsAdmin(false);
    }
    setAuthLoading(false);
  });
  return () => unsubscribe();
}, []);

// Songs and state listeners (only when admin)
useEffect(() => {
  if (!isAdmin) return;
  const stateRef = doc(db, 'state', 'nowPlaying');
  const unsubState = onSnapshot(stateRef, (docSnap) => {
    if (docSnap.exists()) setNowPlaying(docSnap.data());
  });

  const songsRef = collection(db, 'songs');
  const q = query(songsRef, orderBy('votes', 'desc'), orderBy('firstVotedAt', 'asc'));
  const unsubSongs = onSnapshot(q, (snapshot) => {
    setSongs(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
  });

  return () => {
    unsubState();
    unsubSongs();
  };
}, [isAdmin]);

const handleLogin = async (e) => {
  e.preventDefault();
  setLoginError('');
  try {
    await signInWithEmailAndPassword(auth, email, password);
  } catch (error) {
    setLoginError('Credenciales incorrectas. Verifica tu email y contraseña.');
  }
};

const handleLogout = async () => {
  await signOut(auth);
};

