 3 | service cloud.firestore {
 4 |   match /databases/{database}/documents {
 5 |     
 6 |     // Regla Global para Admins
 7 |     // Otorga acceso total si el UID del usuario está en la colección 'admins'
 8 |     match /{document=**} {
 9 |       allow read, write: if request.auth != null && exists(/databases/$(database)/documents/admins/$(request.auth.uid));
10 |     }
11 | 
12 |     // 1. Colección de canciones (songs) - Cola Activa
13 |     match /songs/{songId} {
14 |       // Todos pueden leer las canciones para ver la cola y los votos
15 |       allow read: if true;
16 |       
17 |       // Permitir la CREACIÓN si:
18 |       // a) El usuario está logueado.
19 |       // b) El valor inicial de votos es 1.
20 |       allow create: if request.auth != null
21 |                     && request.resource.data.votes == 1;
22 | 
23 |       // Permitir la ACTUALIZACIÓN de votos SOLO si:
24 |       // a) El usuario está logueado.
25 |       // b) Solo se está modificando 'votes' (incremento de +1) y 'firstVotedAt'.
26 |       allow update: if request.auth != null 
27 |                     && (request.resource.data.diff(resource.data).affectedKeys().hasOnly(['votes', 'firstVotedAt']))
28 |                     && request.resource.data.votes == resource.data.votes + 1;
29 |                     
30 |       // Solo admins pueden borrar (vía regla global)
31 |       allow delete: if false;
32 |     }
33 | 
34 |     // 2. Catálogo completo (Estructura estática)
35 |     match /catalog/full_list {
36 |       allow read: if true;
37 |       allow write: if false; // Solo admins (regla global)
38 |     }
39 | 
40 |     // 3. Estado de reproducción (state)
41 |     match /state/{document=**} {
42 |       allow read: if true;
43 |       allow write: if false; 
44 |     }
45 | 
46 |     // 4. Usuarios y tokens (users)
47 |     match /users/{userId} {
48 |       allow read, write: if request.auth != null && request.auth.uid == userId;
49 |     }
50 | 
51 |     // 5. Comandos (commands)
52 |     match /commands/{commandId} {
53 |       allow read: if false;
54 |       allow write: if false; // Solo admins (regla global)
55 |     }
56 | 
57 |     // 6. Sugerencias (suggestions)
58 |     match /suggestions/{docId} {
59 |       allow create: if request.auth != null;
60 |       allow read, update, delete: if false;
61 |     }
62 | 
63 |     // 7. Estadísticas (statistics)
64 |     match /statistics/{docId} {
65 |       allow read: if true;
66 |       allow write: if request.auth != null;
67 |     }
68 |   }
69 | }

