import { useState } from 'react';
import { updateDoc, doc } from 'firebase/firestore';
import { X, Gift, Trophy, Music, Calendar, TrendingUp, Star } from 'lucide-react';
import { db } from './firebase';

const LEVELS = [
  { min: 0, max: 99, icon: '🎵' },
  { min: 100, max: 499, icon: '🎶' },
  { min: 500, max: 1999, icon: '🎧' },
  { min: 2000, max: 4999, icon: '🌀' },
  { min: 5000, max: Infinity, icon: '👑' },
];

const ACHIEVEMENT_ICONS = {
  first_vote: '🎵',
  protagonist: '🌟',
  hitmaker: '🔥',
  influencer: '📣',
  streak: '⚡',
  loyal: '🍻',
  early_bird: '🌅',
  night_owl: '🌙',
};

const EXCHANGE_COST = 50;

export default function Profile({ userData, userId, t, onClose, onLogout }) {
  const [historyFilter, setHistoryFilter] = useState('all');
  const [exchanging, setExchanging] = useState(false);
  const [exchangeMsg, setExchangeMsg] = useState('');

  if (!userData) return null;

  const totalEarned = userData.totalPointsEarned || 0;
  const currentPoints = userData.points || 0;
  const freeVotes = userData.freeVotes || 0;
  const achievements = userData.achievements || [];
  const history = userData.history || [];
  const visitDates = userData.visitDates || [];
  const isRegistered = userData.isRegistered || false;

  // Calcular nivel
  const currentLevel = LEVELS.find(l => totalEarned >= l.min && totalEarned <= l.max) || LEVELS[0];
  const nextLevel = LEVELS.find(l => l.min > totalEarned);
  const levelName = getLevelName(currentLevel.min, t);
  const nextLevelName = nextLevel ? getLevelName(nextLevel.min, t) : null;
  const progressPct = nextLevel
    ? Math.round(((totalEarned - currentLevel.min) / (nextLevel.min - currentLevel.min)) * 100)
    : 100;

  // Estadísticas
  const totalVotesCast = (userData.votes || []).length;
  const totalProposalsMade = (userData.proposals || []).length;
  const playedSongs = history.filter(h => h.status === 'played').length;
  const successRate = totalProposalsMade > 0 ? Math.round((playedSongs / totalProposalsMade) * 100) : 0;
  const nightsVisited = visitDates.length;

  // Logros
  const allAchievements = [
    { id: 'first_vote', title: t.achievementFirstVote, desc: t.achievementFirstVoteDesc },
    { id: 'protagonist', title: t.achievementProtagonist, desc: t.achievementProtagonistDesc },
    { id: 'hitmaker', title: t.achievementHitmaker, desc: t.achievementHitmakerDesc },
    { id: 'influencer', title: t.achievementInfluencer, desc: t.achievementInfluencerDesc },
    { id: 'streak', title: t.achievementStreak, desc: t.achievementStreakDesc },
    { id: 'loyal', title: t.achievementLoyal, desc: t.achievementLoyalDesc },
    { id: 'early_bird', title: t.achievementEarlyBird, desc: t.achievementEarlyBirdDesc },
    { id: 'night_owl', title: t.achievementNightOwl, desc: t.achievementNightOwlDesc },
  ];

  // Filtrar historial
  const filteredHistory = historyFilter === 'all'
    ? history
    : history.filter(h => h.status === historyFilter);

  const handleExchange = async () => {
    if (currentPoints < EXCHANGE_COST) {
      setExchangeMsg(t.notEnoughPoints);
      return;
    }
    setExchanging(true);
    try {
      const userRef = doc(db, 'users', userId);
      await updateDoc(userRef, {
        points: currentPoints - EXCHANGE_COST,
        freeVotes: freeVotes + 1
      });
      setExchangeMsg(t.exchangeSuccess);
    } catch (error) {
      setExchangeMsg(t.authErrorGeneric);
    }
    setExchanging(false);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-zinc-950 flex flex-col">
      {/* Header */}
      <header className="p-4 border-b border-brand-gold/20 flex items-center justify-between shrink-0">
        <h2 className="text-xl font-bold text-brand-gold flex items-center gap-2">
          <Trophy size={24} />
          {t.profileTitle}
        </h2>
        <button onClick={onClose} className="p-2 text-zinc-400 hover:text-white transition-colors">
          <X size={24} />
        </button>
      </header>

      <main className="flex-1 overflow-y-auto p-6 space-y-8">
        {/* Tarjeta de nivel y puntos */}
        <div className="bg-gradient-to-br from-zinc-900 to-zinc-950 border border-brand-gold/30 rounded-2xl p-6 text-center">
          <div className="text-6xl mb-2">{currentLevel.icon}</div>
          <h3 className="font-serif text-2xl font-black text-brand-gold uppercase tracking-wider">{levelName}</h3>
          <p className="text-zinc-400 text-sm mt-1">{t.totalPointsLabel}: <span className="text-brand-gold font-bold">{totalEarned}</span></p>

          {/* Barra de progreso al siguiente nivel */}
          {nextLevel && (
            <div className="mt-4">
              <div className="flex justify-between text-xs text-zinc-500 mb-1">
                <span>{currentLevel.min}</span>
                <span>{nextLevelName} ({nextLevel.min})</span>
              </div>
              <div className="h-2 bg-zinc-800 rounded-full overflow-hidden">
                <div className="h-full bg-gradient-to-r from-brand-gold to-brand-neon-purple rounded-full transition-all duration-500" style={{ width: `${progressPct}%` }} />
              </div>
            </div>
          )}

          {/* Puntos actuales + canjeo */}
          {isRegistered && (
            <div className="mt-6 flex items-center justify-between bg-zinc-950/50 rounded-xl p-4 border border-zinc-800">
              <div className="text-left">
                <p className="text-sm text-zinc-400">{t.points}</p>
                <p className="text-2xl font-bold text-brand-neon-green">{currentPoints}</p>
              </div>
              <div className="text-right">
                <p className="text-sm text-zinc-400">{t.freeVotesLabel}</p>
                <p className="text-2xl font-bold text-brand-gold">{freeVotes}</p>
              </div>
            </div>
          )}

          {isRegistered && (
            <button
              onClick={handleExchange}
              disabled={exchanging || currentPoints < EXCHANGE_COST}
              className={`mt-4 w-full font-bold py-3 rounded-xl flex items-center justify-center gap-2 transition-all ${
                currentPoints >= EXCHANGE_COST
                  ? 'bg-gradient-to-r from-brand-neon-purple to-brand-neon-green text-white hover:opacity-90 active:scale-[0.98]'
                  : 'bg-zinc-800 text-zinc-500 cursor-not-allowed'
              }`}
            >
              <Gift size={18} />
              {t.exchangeButton}
            </button>
          )}
          {exchangeMsg && <p className="text-sm text-center mt-2 text-brand-gold">{exchangeMsg}</p>}
        </div>

        {/* Estadísticas personales */}
        <div>
          <h3 className="text-brand-gold font-bold uppercase tracking-wider text-sm flex items-center gap-2 mb-4">
            <TrendingUp size={16} />
            {t.myStats}
          </h3>
          <div className="grid grid-cols-2 gap-3">
            <StatCard icon={<Music size={18} />} label={t.totalVotesCast} value={totalVotesCast} />
            <StatCard icon={<Star size={18} />} label={t.totalProposalsMade} value={totalProposalsMade} />
            <StatCard icon={<TrendingUp size={18} />} label={t.successRate} value={`${successRate}%`} />
            <StatCard icon={<Calendar size={18} />} label={t.nightsVisited} value={nightsVisited} />
          </div>
        </div>

        {/* Logros */}
        <div>
          <h3 className="text-brand-gold font-bold uppercase tracking-wider text-sm flex items-center gap-2 mb-4">
            <Trophy size={16} />
            {t.achievementsTitle}
            <span className="text-zinc-500 text-xs">({achievements.length}/{allAchievements.length})</span>
          </h3>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            {allAchievements.map(ach => {
              const unlocked = achievements.includes(ach.id);
              return (
                <div
                  key={ach.id}
                  className={`rounded-xl p-4 border text-center transition-all ${
                    unlocked
                      ? 'bg-brand-gold/10 border-brand-gold/30'
                      : 'bg-zinc-900 border-zinc-800 opacity-40'
                  }`}
                >
                  <div className={`text-3xl mb-1 ${unlocked ? '' : 'grayscale'}`}>
                    {ACHIEVEMENT_ICONS[ach.id] || '🔒'}
                  </div>
                  <p className={`text-xs font-bold ${unlocked ? 'text-brand-gold' : 'text-zinc-500'}`}>{ach.title}</p>
                  <p className="text-[10px] text-zinc-500 mt-1">{ach.desc}</p>
                </div>
              );
            })}
          </div>
        </div>

        {/* Historial de canciones */}
        <div>
          <h3 className="text-brand-gold font-bold uppercase tracking-wider text-sm flex items-center gap-2 mb-4">
            <Music size={16} />
            {t.songHistory}
          </h3>

          {/* Filtros */}
          <div className="flex gap-2 mb-4">
            {[
              { id: 'all', label: t.historyAll },
              { id: 'played', label: t.historyPlayed },
              { id: 'in_queue', label: t.historyInQueue },
              { id: 'not_played', label: t.historyNotPlayed },
            ].map(f => (
              <button
                key={f.id}
                onClick={() => setHistoryFilter(f.id)}
                className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
                  historyFilter === f.id
                    ? 'bg-brand-gold text-zinc-950'
                    : 'bg-zinc-900 text-zinc-500 hover:text-zinc-300 border border-zinc-800'
                }`}
              >
                {f.label}
              </button>
            ))}
          </div>

          {/* Lista */}
          {filteredHistory.length === 0 ? (
            <p className="text-center text-zinc-600 py-8">{t.noHistory}</p>
          ) : (
            <div className="space-y-2">
              {filteredHistory.slice().reverse().map((item, i) => (
                <div key={i} className="flex items-center justify-between bg-zinc-900 border border-zinc-800 rounded-xl p-3">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-white truncate">{item.title}</p>
                    <p className="text-xs text-zinc-500 mt-0.5">
                      {item.action === 'propose' ? t.proposed : t.votedByYou}
                    </p>
                  </div>
                  <div className="shrink-0 ml-3">
                    {item.status === 'played' && <span className="text-xs font-bold text-brand-neon-green bg-brand-neon-green/10 px-2 py-1 rounded">{t.historyPlayed}</span>}
                    {item.status === 'in_queue' && <span className="text-xs font-bold text-brand-gold bg-brand-gold/10 px-2 py-1 rounded">{t.historyInQueue}</span>}
                    {item.status === 'not_played' && <span className="text-xs font-bold text-zinc-500 bg-zinc-800 px-2 py-1 rounded">{t.historyNotPlayed}</span>}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Logout (solo registrados) */}
        {isRegistered && (
          <button
            onClick={onLogout}
            className="w-full bg-zinc-900 border border-zinc-800 text-zinc-400 font-bold py-3 rounded-xl hover:bg-zinc-800 hover:text-white transition-all"
          >
            {t.logoutAccount}
          </button>
        )}
      </main>
    </div>
  );
}

function StatCard({ icon, label, value }) {
  return (
    <div className="bg-zinc-900 border border-zinc-800 rounded-xl p-4 text-center">
      <div className="flex justify-center text-brand-gold mb-2">{icon}</div>
      <p className="text-2xl font-bold text-white">{value}</p>
      <p className="text-xs text-zinc-500 mt-1">{label}</p>
    </div>
  );
}

function getLevelName(minPoints, t) {
  if (minPoints >= 5000) return t.levelLeyenda;
  if (minPoints >= 2000) return t.levelMaestro;
  if (minPoints >= 500) return t.levelPro;
  if (minPoints >= 100) return t.levelAficionado;
  return t.levelNovato;
}

