    <Trophy size={16} />{t.achievementsTitle}<span className="text-zinc-500 text-xs">({achievements.length}/{allAchievements.length})</span>
  </h3>
  <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
    {allAchievements.map(ach => {
      const unlocked = achievements.includes(ach.id);
      return (
        <div key={ach.id} className={`rounded-xl p-4 border text-center transition-all ${unlocked ? 'bg-brand-gold/10 border-brand-gold/30' : 'bg-zinc-900 border-zinc-800 opacity-40'}`}>
          <div className={`text-3xl mb-1 ${unlocked ? '' : 'grayscale'}`}>{ACHIEVEMENT_ICONS[ach.id] || '🔒'}</div>
          <p className={`text-xs font-bold ${unlocked ? 'text-brand-gold' : 'text-zinc-500'}`}>{ach.title}</p>
          <p className="text-[10px] text-zinc-500 mt-1">{ach.desc}</p>
        </div>
      );
    })}
  </div>
</div>

        {/* Historial */}
        <div>
          <h3 className="text-brand-gold font-bold uppercase tracking-wider text-sm flex items-center gap-2 mb-4"><Music size={16} />{t.songHistory}</h3>
          <div className="flex gap-2 mb-4">
            {[{id:'all',label:t.historyAll},{id:'played',label:t.historyPlayed},{id:'in_queue',label:t.historyInQueue},{id:'not_played',label:t.historyNotPlayed}].map(f => (
