                className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${historyFilter === f.id ? 'bg-brand-gold text-zinc-950' : 'bg-zinc-900 text-zinc-500 hover:text-zinc-300 border border-zinc-800'}`}>{f.label}</button>
            ))}
          </div>
          {filteredHistory.length === 0 ? (
            <p className="text-center text-zinc-600 py-8">{t.noHistory}</p>
          ) : (
            <div className="space-y-2">
              {filteredHistory.slice().reverse().map((item, i) => (
                <div key={i} className="flex items-center justify-between bg-zinc-900 border border-zinc-800 rounded-xl p-3">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-white truncate">{item.title}</p>
                    <p className="text-xs text-zinc-500 mt-0.5">{item.action === 'propose' ? t.proposed : t.votedByYou}</p>
                  </div>
                  <div className="shrink-0 ml-3">
                    {item.status === 'played' && <span className="text-xs font-bold text-brand-neon-green bg-brand-neon-green/10 px-2 py-1 rounded">{t.historyPlayed}</span>}
                    {item.status === 'in_queue' && <span className="text-xs font-bold text-brand-gold bg-brand-gold/10 px-2 py-1 rounded">{t.historyInQueue}</span>}
                    {item.status === 'not_played' && <span className="text-xs font-bold text-zinc-500 bg-zinc-800 px-2 py-1 rounded">{t.historyNotPlayed}</span>}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

