          <button onClick={onLogout} className="w-full bg-zinc-900 border border-zinc-800 text-zinc-400 font-bold py-3 rounded-xl hover:bg-zinc-800 hover:text-white transition-all">{t.logoutAccount}</button>
        )}
      </main>
    </div>
  );
}

function StatCard({ icon, label, value }) {
  return (
    <div className="bg-zinc-900 border border-zinc-800 rounded-xl p-4 text-center">
      <div className="flex justify-center text-brand-gold mb-2">{icon}</div>
      <p className="text-2xl font-bold text-white">{value}</p>
      <p className="text-xs text-zinc-500 mt-1">{label}</p>
    </div>
  );
}

function getLevelName(minPoints, t) {
  if (minPoints >= 5000) return t.levelLeyenda;
  if (minPoints >= 2000) return t.levelMaestro;
  if (minPoints >= 500) return t.levelPro;
  if (minPoints >= 100) return t.levelAficionado;
  return t.levelNovato;
}

